WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')), alvo AS (SELECT p.pedido_id FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) WHERE p.pedido_id = :pedido_id AND p.status IN ('aguardando_anexo', 'precisa_catalogo', 'falhou') AND p.execucao_atual IS NULL) INSERT INTO pedido_arquivos (pedido_id, tipo, parte, conteudo_base64) SELECT alvo.pedido_id, 'anexo', CAST(:parte AS INTEGER), :conteudo FROM alvo ON CONFLICT (pedido_id, tipo, parte) DO UPDATE SET conteudo_base64 = EXCLUDED.conteudo_base64, atualizado_em = now() RETURNING pedido_id, parte
